begin;
select plan(17);
select has_table('public', 'departments', 'departments table exists');
select has_table('public', 'department_memberships', 'department memberships table exists');
select has_table('public', 'equipment', 'equipment table exists');
select has_table('public', 'projects', 'projects table exists');
select has_table('public', 'booking_requests', 'booking requests table exists');
select has_table('public', 'faculty_approvals', 'faculty approvals table exists');
select ok((select relrowsecurity from pg_class where oid = 'public.departments'::regclass), 'departments has RLS enabled');
select ok((select relrowsecurity from pg_class where oid = 'public.equipment'::regclass), 'equipment has RLS enabled');
select ok((select relrowsecurity from pg_class where oid = 'public.department_memberships'::regclass), 'department memberships has RLS enabled');
select ok((select relrowsecurity from pg_class where oid = 'public.projects'::regclass), 'projects has RLS enabled');
select ok((select relrowsecurity from pg_class where oid = 'public.booking_requests'::regclass), 'booking requests has RLS enabled');
select ok((select relrowsecurity from pg_class where oid = 'public.faculty_approvals'::regclass), 'faculty approvals has RLS enabled');
select ok(exists (select 1 from pg_constraint where conrelid = 'public.booking_requests'::regclass and conname = 'booking_active_slot_no_overlap' and contype = 'x' and pg_get_constraintdef(oid) like '%tstzrange%'), 'equipment slots have a GiST exclusion constraint');
select ok(exists (select 1 from pg_constraint where conrelid = 'public.booking_requests'::regclass and conname = 'booking_active_slot_no_overlap' and pg_get_constraintdef(oid) like '%approved%' and pg_get_constraintdef(oid) not like '%pending%'), 'only approved allocations participate in overlap prevention');
select ok(exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'projects' and policyname = 'projects_create_for_member_department'), 'project creation requires membership in the project department');
select ok(to_regprocedure('public.review_booking_request(uuid, public.approval_decision, text)') is not null, 'faculty review uses the authorized database RPC');
select ok(to_regprocedure('private.validate_booking_window()') is not null, 'booking starts must be in the future');
select * from finish();
rollback;
